import { useEffect, useState } from 'react';

function Checkout() {
  const [order, setOrder] = useState(null);
  const [method, setMethod] = useState(null);
  const [paymentId, setPaymentId] = useState(null);
  const [status, setStatus] = useState('idle');
  const [vpa, setVpa] = useState('');
  const [card, setCard] = useState({
    number: '',
    expiry: '',
    cvv: '',
    name: ''
  });

  const params = new URLSearchParams(window.location.search);
  const orderId = params.get('order_id');

  /* 1️⃣ Fetch order on load */
  useEffect(() => {
    if (!orderId) return;

    fetch(`http://localhost:8000/api/v1/orders/${orderId}/public`)
      .then(res => res.json())
      .then(data => setOrder(data))
      .catch(() => setStatus('error'));
  }, [orderId]);

  /* 2️⃣ Poll payment status */
  useEffect(() => {
    if (!paymentId) return;

    const interval = setInterval(() => {
      fetch(`http://localhost:8000/api/v1/payments/${paymentId}/public`)
        .then(res => res.json())
        .then(data => {
          if (data.status === 'success' || data.status === 'failed') {
            setStatus(data.status);
            clearInterval(interval);
          }
        });
    }, 2000);

    return () => clearInterval(interval);
  }, [paymentId]);

  /* 3️⃣ Create payment */
  const handlePayment = (e) => {
    e.preventDefault();
    setStatus('processing');

    const payload = { order_id: orderId, method };

    if (method === 'upi') payload.vpa = vpa;

    if (method === 'card') {
      const [month, year] = card.expiry.split('/');
      payload.card = {
        number: card.number,
        expiry_month: month,
        expiry_year: year,
        cvv: card.cvv,
        holder_name: card.name
      };
    }

    fetch('http://localhost:8000/api/v1/payments/public', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    })
      .then(res => res.json())
      .then(data => setPaymentId(data.id))
      .catch(() => setStatus('error'));
  };

  if (!order) return null;

  return (
    <div
      data-test-id="checkout-container"
      style={{
        maxWidth: '420px',
        margin: '60px auto',
        padding: '28px',
        background: '#ffffff',
        borderRadius: '12px',
        boxShadow: '0 10px 25px rgba(0,0,0,0.08)',
        fontFamily: 'Inter, Arial, sans-serif'
      }}
    >

      {/* Order Summary */}
      <div data-test-id="order-summary" style={{ marginBottom: '24px' }}>
        <h2 style={{ marginBottom: '12px' }}>Complete Payment</h2>
        <div>
          <span>Amount: </span>
          <span data-test-id="order-amount" style={{ fontWeight: 600 }}>
            ₹{(order.amount / 100).toFixed(2)}
          </span>
        </div>
        <div>
          <span>Order ID: </span>
          <span data-test-id="order-id" style={{ fontWeight: 600 }}>
            {order.id}
          </span>
        </div>
      </div>

      {/* Payment Method Selection */}
      {status === 'idle' && (
        <div data-test-id="payment-methods">
          <button
            data-test-id="method-upi"
            onClick={() => setMethod('upi')}
            style={{
              width: '100%',
              padding: '12px',
              marginBottom: '10px',
              borderRadius: '8px',
              border: 'none',
              background: '#2563eb',
              color: '#fff',
              cursor: 'pointer'
            }}
          >
            UPI
          </button>

          <button
            data-test-id="method-card"
            onClick={() => setMethod('card')}
            style={{
              width: '100%',
              padding: '12px',
              borderRadius: '8px',
              border: '1px solid #2563eb',
              background: '#ffffff',
              color: '#2563eb',
              cursor: 'pointer'
            }}
          >
            Card
          </button>
        </div>
      )}

      {/* UPI Form */}
      {method === 'upi' && status === 'idle' && (
        <form data-test-id="upi-form" onSubmit={handlePayment}>
          <input
            data-test-id="vpa-input"
            placeholder="username@bank"
            value={vpa}
            onChange={e => setVpa(e.target.value)}
            style={{
              width: '100%',
              padding: '10px',
              marginTop: '12px',
              borderRadius: '6px',
              border: '1px solid #d1d5db'
            }}
          />
          <button
            data-test-id="pay-button"
            type="submit"
            style={{
              width: '100%',
              padding: '12px',
              marginTop: '12px',
              borderRadius: '8px',
              border: 'none',
              background: '#16a34a',
              color: '#fff',
              cursor: 'pointer'
            }}
          >
            Pay ₹{(order.amount / 100).toFixed(0)}
          </button>
        </form>
      )}

      {/* Card Form */}
      {method === 'card' && status === 'idle' && (
        <form data-test-id="card-form" onSubmit={handlePayment}>
          {[
            { id: 'card-number-input', placeholder: 'Card Number', key: 'number' },
            { id: 'expiry-input', placeholder: 'MM/YY', key: 'expiry' },
            { id: 'cvv-input', placeholder: 'CVV', key: 'cvv' },
            { id: 'cardholder-name-input', placeholder: 'Name on Card', key: 'name' }
          ].map(field => (
            <input
              key={field.id}
              data-test-id={field.id}
              placeholder={field.placeholder}
              value={card[field.key]}
              onChange={e => setCard({ ...card, [field.key]: e.target.value })}
              style={{
                width: '100%',
                padding: '10px',
                marginTop: '10px',
                borderRadius: '6px',
                border: '1px solid #d1d5db'
              }}
            />
          ))}

          <button
            data-test-id="pay-button"
            type="submit"
            style={{
              width: '100%',
              padding: '12px',
              marginTop: '12px',
              borderRadius: '8px',
              border: 'none',
              background: '#16a34a',
              color: '#fff',
              cursor: 'pointer'
            }}
          >
            Pay ₹{(order.amount / 100).toFixed(0)}
          </button>
        </form>
      )}

      {/* Processing */}
      {status === 'processing' && (
        <div
          data-test-id="processing-state"
          style={{ textAlign: 'center', marginTop: '20px', fontWeight: 600 }}
        >
          <span data-test-id="processing-message">
            Processing payment...
          </span>
        </div>
      )}

      {/* Success */}
      {status === 'success' && (
        <div
          data-test-id="success-state"
          style={{ textAlign: 'center', color: '#16a34a', marginTop: '20px' }}
        >
          <h2>Payment Successful!</h2>
          <div>
            <span>Payment ID: </span>
            <span data-test-id="payment-id">{paymentId}</span>
          </div>
          <span data-test-id="success-message">
            Your payment has been processed successfully
          </span>
        </div>
      )}

      {/* Error */}
      {(status === 'failed' || status === 'error') && (
        <div
          data-test-id="error-state"
          style={{ textAlign: 'center', color: '#dc2626', marginTop: '20px' }}
        >
          <h2>Payment Failed</h2>
          <span data-test-id="error-message">
            Payment could not be processed
          </span>
          <button
            data-test-id="retry-button"
            onClick={() => window.location.reload()}
            style={{
              marginTop: '12px',
              padding: '10px 16px',
              borderRadius: '6px',
              border: 'none',
              background: '#dc2626',
              color: '#fff',
              cursor: 'pointer'
            }}
          >
            Try Again
          </button>
        </div>
      )}

    </div>
  );
}

export default Checkout;
